package com.firesms.app.domain.rules

import kotlinx.serialization.SerializationException
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonNull
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive

/** The subset of parser-rule fields that can be generated by an LLM and imported. */
data class ImportedRuleFields(
    val bodyPattern: String,
    val amountTemplate: String,
    val descriptionSource: String,
    val descriptionValue: String,
    val type: String,
    val datePattern: String,
    val dateFormat: String,
    val remarksPattern: String,
    val remarksTemplate: String
)

sealed interface RuleJsonImportResult {
    data class Success(
        val fields: ImportedRuleFields,
        val repairedInvalidEscapes: Boolean = false
    ) : RuleJsonImportResult

    data class Error(val message: String) : RuleJsonImportResult
}

private data class RuleJsonPayload(
    val bodyPattern: String,
    val amountTemplate: String,
    val descriptionSource: String,
    val descriptionValue: String,
    val type: String,
    val datePattern: String? = null,
    val dateFormat: String? = null,
    val remarksPattern: String? = null,
    val remarksTemplate: String? = null
)

object RuleJsonImporter {

    private val JSON_ESCAPES = setOf('"', '\\', '/', 'b', 'f', 'n', 'r', 't', 'u')
    private val ERROR_OFFSET = Regex("""offset (\d+)""")

    fun parse(input: String): RuleJsonImportResult {
        val normalized = stripMarkdownFence(input)
        if (normalized.isBlank()) {
            return RuleJsonImportResult.Error("Paste the rule JSON first.")
        }
        val repairedInput = repairInvalidJsonEscapes(normalized)

        val payload = try {
            decodePayload(repairedInput.value)
        } catch (e: SerializationException) {
            val offset = repairedInput.originalOffset(jsonErrorOffset(e.message))
            val where = offset?.let { " at ${describePosition(input, normalized, it)}" }.orEmpty()
            val detail = jsonErrorDetail(e.message)?.let { " ($it)" }.orEmpty()
            return RuleJsonImportResult.Error(
                "Invalid rule JSON$where$detail. Check for missing quotes, commas or braces."
            )
        } catch (e: Exception) {
            return RuleJsonImportResult.Error("Invalid rule JSON: ${e.message ?: "unable to read input"}")
        }

        val datePattern = payload.datePattern.orEmpty()
        val dateFormat = payload.dateFormat.orEmpty()
        val remarksPattern = payload.remarksPattern.orEmpty()
        val remarksTemplate = payload.remarksTemplate.orEmpty()
        RuleValidator.validate(
            bodyPattern = payload.bodyPattern,
            amountTemplate = payload.amountTemplate,
            descriptionSource = payload.descriptionSource,
            descriptionValue = payload.descriptionValue,
            type = payload.type,
            datePattern = datePattern,
            dateFormat = dateFormat,
            remarksPattern = remarksPattern,
            remarksTemplate = remarksTemplate
        )?.let { return RuleJsonImportResult.Error(it) }

        return RuleJsonImportResult.Success(
            fields = ImportedRuleFields(
                bodyPattern = payload.bodyPattern,
                amountTemplate = payload.amountTemplate,
                descriptionSource = payload.descriptionSource,
                descriptionValue = payload.descriptionValue,
                type = payload.type,
                datePattern = datePattern,
                dateFormat = dateFormat,
                remarksPattern = remarksPattern,
                remarksTemplate = remarksTemplate
            ),
            repairedInvalidEscapes = repairedInput.repaired
        )
    }

    private fun decodePayload(input: String): RuleJsonPayload {
        val jsonObject = Json.parseToJsonElement(input) as? JsonObject
            ?: throw IllegalArgumentException("The imported JSON must be an object.")

        fun requiredString(name: String): String {
            val value = jsonObject[name]
                ?: throw IllegalArgumentException("${fieldName(name)} is missing.")
            return (value as? JsonPrimitive)
                ?.takeIf { it.isString }
                ?.content
                ?: throw IllegalArgumentException("${fieldName(name)} must be text in quotes.")
        }

        fun optionalString(name: String): String? {
            val value = jsonObject[name] ?: return null
            if (value === JsonNull) return null
            return (value as? JsonPrimitive)
                ?.takeIf { it.isString }
                ?.content
                ?: throw IllegalArgumentException("${fieldName(name)} must be text in quotes, or null.")
        }

        return RuleJsonPayload(
            bodyPattern = requiredString("bodyPattern"),
            amountTemplate = requiredString("amountTemplate"),
            descriptionSource = requiredString("descriptionSource"),
            descriptionValue = requiredString("descriptionValue"),
            type = requiredString("type"),
            datePattern = optionalString("datePattern"),
            dateFormat = optionalString("dateFormat"),
            remarksPattern = optionalString("remarksPattern"),
            remarksTemplate = optionalString("remarksTemplate")
        )
    }

    /** The editor label with the JSON key, e.g. `Amount template ("amountTemplate")`. */
    private fun fieldName(key: String): String = "${RuleValidator.labelFor(key)} (\"$key\")"

    private fun jsonErrorOffset(message: String?): Int? =
        message?.let { ERROR_OFFSET.find(it) }?.groupValues?.get(1)?.toIntOrNull()

    /** The parser's own explanation, without its offset prefix, JSON path and echoed input. */
    private fun jsonErrorDetail(message: String?): String? {
        val text = message ?: return null
        val afterOffset = ERROR_OFFSET.find(text)?.let { text.substring(it.range.last + 1).removePrefix(":") } ?: text
        return afterOffset
            .substringBefore('\n')
            .substringBefore(" at path")
            .trim()
            .trimEnd('.')
            .ifBlank { null }
    }

    /**
     * `line 2, column 5, near "…"` for an [offset] into [normalized], counted in [input] as the
     * user pasted it, including any surrounding code fence.
     */
    internal fun describePosition(input: String, normalized: String, offset: Int): String {
        val base = input.indexOf(normalized).coerceAtLeast(0)
        val position = (base + offset).coerceIn(0, input.length)
        val before = input.substring(0, position)
        val line = before.count { it == '\n' } + 1
        val column = position - (before.lastIndexOf('\n') + 1) + 1
        val near = input.substring(position, (position + 12).coerceAtMost(input.length))
            .substringBefore('\n')
        return if (near.isBlank()) "line $line, column $column (end of input)"
        else "line $line, column $column, near \"$near\""
    }

    private data class RepairedJsonInput(
        val value: String,
        val repaired: Boolean,
        /** Offsets in [value] of the backslashes added by the repair. */
        val insertedAt: List<Int> = emptyList()
    ) {
        /** Maps an offset in [value] back to the input before the repair. */
        fun originalOffset(offset: Int?): Int? = offset?.let { o -> o - insertedAt.count { it < o } }
    }

    /**
     * LLMs commonly emit regex escapes such as \s in otherwise valid JSON. JSON only accepts
     * a small escape set, so insert the missing escape backslash while leaving valid JSON
     * escapes (including newlines, quotes, Unicode escapes, and already doubled slashes) intact.
     */
    private fun repairInvalidJsonEscapes(input: String): RepairedJsonInput {
        val output = StringBuilder(input.length)
        var insideString = false
        var repaired = false
        val insertedAt = mutableListOf<Int>()
        var index = 0

        while (index < input.length) {
            val char = input[index]
            if (!insideString) {
                output.append(char)
                if (char == '"') insideString = true
                index++
                continue
            }

            when (char) {
                '"' -> {
                    output.append(char)
                    insideString = false
                    index++
                }
                '\\' -> {
                    if (index + 1 >= input.length) {
                        output.append(char)
                        index++
                        continue
                    }

                    val escaped = input[index + 1]
                    if (escaped in JSON_ESCAPES) {
                        output.append(char).append(escaped)
                    } else {
                        insertedAt += output.length
                        output.append("\\\\").append(escaped)
                        repaired = true
                    }
                    index += 2
                }
                else -> {
                    output.append(char)
                    index++
                }
            }
        }

        return RepairedJsonInput(output.toString(), repaired, insertedAt)
    }

    private fun stripMarkdownFence(input: String): String {
        val trimmed = input.trim()
        if (!trimmed.startsWith("```")) return trimmed

        val firstLineEnd = trimmed.indexOf('\n')
        if (firstLineEnd == -1) return trimmed

        val closingFence = trimmed.lastIndexOf("```")
        if (closingFence <= firstLineEnd) return trimmed

        return trimmed.substring(firstLineEnd + 1, closingFence).trim()
    }
}
